<?phpnamespace app\api\controller\user;use app\api\controller\Controller;use app\api\model\Order as OrderModel;use app\api\model\CouponUser as CouponUserModel;use app\api\model\User as UserModel;use hema\wechat\Pay as WxPay;use hema\alipay\Driver as AlipayPay;use think\facade\Cache;/** * 个人中心主页 */class Index extends Controller{    private $user;    /**     * 构造方法     */    public function initialize()    {        parent::initialize();        $this->user = $this->getUserDetail();   // 用户信息    }         /**     * 获取用户中心信息     */	public function index()    {        //优惠券数量        $couponCount = CouponUserModel::getUserCount($this->user_id);        // 订单总数        $model = new OrderModel;        $orderCount = [            'payment' => $model->getOrderClassCount('payment',$this->user_id),            'comment' => $model->getOrderClassCount('comment',$this->user_id),            'refund10' => $model->getOrderClassCount('refund10',$this->user_id)        ];        return $this->renderSuccess(compact('orderCount','couponCount'));    }        /**     * 开通会员     */    public function openVip()    {        $model = UserModel::get($this->user_id);        if ($model->openVip()) {            return $this->renderMsg('开通成功');        }        $error = $model->getError() ?: '开通失败';		return $this->renderError($error);    }        /**     * 购买会员     * $pay_mode 1=微信 3=支付宝     * $browser 浏览器类型，只有H5才会传递     */    public function buyVip($money,$pay_mode,$browser='')    {        $order_no = order_no();        $order = [            'order_no' => $order_no,            'pay_mode' => $pay_mode,//支付类型            'money' => $money,            'remark' => '购买会员卡',            'user_id' => $this->user['user_id']        ];        Cache::set($order_no, $order,7200);                $mp = $this->mp;        //微信支付        if($pay_mode == 1){            $wx = new WxPay;            //网页其它浏览器平台支付接口            if($mp == 'h5' and $browser == 'other'){                if(!$result = $wx->h5($order_no,$money,'api/notify/buyvip','购买会员卡')){                    return $this->renderError($wx->getError());                }            }            //微信小程序或微信浏览器支付接口            if($mp == 'weixin' or ($mp == 'h5' and $browser == 'weixin')){                if(!$result = $wx->jsapi($order_no,$money,$this->user['open_id'],'api/notify/buyvip','购买会员卡')){                    return $this->renderError($wx->getError());                }            }        }        //支付宝支付        if($pay_mode == 4){            //非微信浏览器支付接口            if($mp == 'h5' and $browser != 'weixin'){                $alipay = new AlipayPay('aliweb');                if(!$result = $alipay->tradeWapPay($order_no,$money,'api/notify/buyvip/mode/aliweb','h5/#/pages/index/index','购买会员卡')){                    $this->error = $alipay->getError();                    return false;                }            }            //支付宝小程序支付接口            if($mp == 'alipay'){                $alipay = new AlipayPay('aliapp');                if(!$result = $alipay->tradeCreate($order_no,$money,$this->user['alipay_open_id'],'api/notify/buyvip/mode/aliapp','购买会员卡')){                    $this->error = $alipay->getError();                    return false;                }            }        }        return $this->renderSuccess([            'payment' => $result        ]);    }    }